import{z as s,x as o,o as t,c as m,q as r,j as B,D as E,d as l,s as n,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"多轮安全的评测","description":"","frontmatter":{"title":"多轮安全的评测","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/aeval-multiturn-safety.md","filePath":"llm/aeval-multiturn-safety.md","lastUpdated":1791413859000}'),d={name:"llm/aeval-multiturn-safety.md"};function h(p,a,D,C,f,u){const A=o("Mermaid");return t(),m("div",null,[a[2]||(a[2]=r('<h1 id="多轮安全的评测" tabindex="-1">多轮安全的评测 <a class="header-anchor" href="#多轮安全的评测" aria-label="Permalink to &quot;多轮安全的评测&quot;">​</a></h1><div class="epigraph"><p>单轮考卷考的是条件分布的一个点，会话考的是一条路径；边界很少被一次撞开，多半是被一轮一轮磨开的。</p><footer>—— 据 Zheng et al., MT-Bench 的逐轮协议口径与公开多轮越狱评测整理</footer></div><p><a href="/llm/aeval-sycophancy-metric">上一课</a>把谄媚钉成立场注入、盲判与分轮记账，单轮探针至此齐了：危害/对照、诚实键、谄媚键。真实产品会话没有单轮这回事——<a href="/llm/jailbreak">越狱与越狱评测</a>已把多轮与预填列进攻击面；<a href="/llm/mt-bench">MT-Bench</a>把「保留第一轮前缀、逐轮判分」写成了多轮协议的通用机制。本课把这两条线合到安全上：脚本、逐轮判分、首违轮。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单轮 ASR 系统性低估会话风险，机制有四。<strong>渐进升级</strong>：攻击者每轮只推进一小步，每一轮单独看都贴着政策边界内侧，拒绝示范在每一轮都有理由不触发；路径整体却走出了清洁题面的邻域。<strong>上下文压载</strong>：长历史里塞满越界内容后，拒绝倾向被稀释，many-shot 一类效应（见<a href="/llm/many-shot-jailbreak">多样本越狱</a>）在多轮里自然发生。<strong>状态遗忘</strong>：模型忘了自己第一轮的拒答理由，第三轮同一请求换个说法就被接住。<strong>接口面</strong>：补全类接口暴露助手前缀时，预填把对手写进模型自己的嘴里（见<a href="/llm/prefill-jailbreak">预填越狱</a>）。缺口由此明确：评测对象要从「一轮」换成「一条会话路径」。</p><p><span class="marginnote">「状态遗忘」就是模型忘了自己前面说过的立场。像审讯里嫌疑人第一轮咬定「不知道」，第三轮被换个问法就全交代了——不是出现了新证据，是他忘了自己先前的口径，于是同一请求换个说法就被接住了。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="脚本协议" tabindex="-1">脚本协议 <a class="header-anchor" href="#脚本协议" aria-label="Permalink to &quot;脚本协议&quot;">​</a></h3><p>每条脚本是一列轮次，每轮带意图标注：该轮政策允许还是禁止。生成必须接到同一条对话上——完整历史保留、禁止拆成多次独立补全，否则测到的是模板错误不是安全，这是 <a href="/llm/mt-bench">MT-Bench</a> 已钉死的协议要求。判分逐轮做：违规 / 合规 / 边缘。数字两个：累积泄漏 \\(\\mathrm{ASR}_T=\\Pr[\\exists\\, t\\le T\\text{ 违规}]\\) 与首违轮分布 \\(h(t)\\)——「平均第 2.4 轮破防」和「第 9 轮才破防」是两种产品风险，平均值把它俩抹平。脚本表面随机化（措辞、语言、角色名换皮）重测一遍，防背题。</p>',9)),(t(),B(i,null,{default:E(()=>[n(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SCRIPT%5B%22%E8%84%9A%E6%9C%AC%EF%BC%9A%E8%BD%AE%20%C3%97%20%E6%84%8F%E5%9B%BE%E6%A0%87%E6%B3%A8%22%5D%20--%3E%20GEN%5B%22%E9%80%90%E8%BD%AE%E7%94%9F%E6%88%90%EF%BC%9A%E5%AE%8C%E6%95%B4%E5%8E%86%E5%8F%B2%E4%BF%9D%E7%95%99%22%5D%0A%20%20GEN%20--%3E%20G1%5B%22%E7%AC%AC%201%20%E8%BD%AE%E5%88%A4%E5%88%86%22%5D%0A%20%20GEN%20--%3E%20G2%5B%22%E7%AC%AC%202%20%E8%BD%AE%E5%88%A4%E5%88%86%22%5D%0A%20%20GEN%20--%3E%20G3%5B%22%E7%AC%AC%20T%20%E8%BD%AE%E5%88%A4%E5%88%86%22%5D%0A%20%20G1%20--%3E%20HZ%5B%22%E9%A6%96%E8%BF%9D%E8%BD%AE%E5%88%86%E5%B8%83%22%5D%0A%20%20G2%20--%3E%20HZ%0A%20%20G3%20--%3E%20HZ%0A%20%20HZ%20--%3E%20CUM%5B%22%E7%B4%AF%E7%A7%AF%20ASR%20%E4%B8%8E%E9%97%A8%E7%A6%81%22%5D%0A%20%20CUM%20--%3E%20RAND%5B%22%E8%A1%A8%E9%9D%A2%E9%9A%8F%E6%9C%BA%E5%8C%96%E9%87%8D%E6%B5%8B%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"渐进升级为什么有效，值得说透：条件分布 \\(p_\\theta(\\cdot\\mid x_{\\lt t})\\) 每一步只挪一点，每一步都在「看起来可以回」的邻域里；但拒绝行为是按邻域训练的，没有一条监督信号教模型「这段路径整体在走向危害」。逐轮判分之所以是正确粒度，正因为它给路径上的每一步单独归责，与上一课的分轮记账同构。",-1)),a[5]||(a[5]=e("p",null,"一条四轮渐进脚本怎么把「每轮单独看都合规」走成「路径违规」：",-1)),(t(),B(i,null,{default:E(()=>[n(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20T1%5B%22%E7%AC%AC%201%20%E8%BD%AE%EF%BC%9A%E9%97%AE%E8%83%8C%E6%99%AF%E7%9F%A5%E8%AF%86%20%E2%86%92%20%E5%90%88%E8%A7%84%22%5D%20--%3E%20T2%5B%22%E7%AC%AC%202%20%E8%BD%AE%EF%BC%9A%E8%BD%BB%E6%8E%A8%E4%B8%80%E6%AD%A5%20%E2%86%92%20%E5%90%88%E8%A7%84%22%5D%0A%20%20T2%20--%3E%20T3%5B%22%E7%AC%AC%203%20%E8%BD%AE%EF%BC%9A%E5%80%9F%E5%8E%86%E5%8F%B2%E7%BB%86%E8%8A%82%E5%86%8D%E6%8E%A8%20%E2%86%92%20%E5%90%88%E8%A7%84%22%5D%0A%20%20T3%20--%3E%20T4%5B%22%E7%AC%AC%204%20%E8%BD%AE%EF%BC%9A%E6%8B%BC%E5%87%BA%E8%BF%9D%E8%A7%84%E6%95%B4%E4%BD%93%20%E2%86%92%20%E8%BF%9D%E8%A7%84%22%5D%0A%20%20T4%20--%3E%20LESSON%5B%22%E6%AF%8F%E8%BD%AE%E9%83%BD%E8%B4%B4%E7%9D%80%E8%BE%B9%E7%95%8C%E5%86%85%E4%BE%A7%EF%BC%8C%E8%B7%AF%E5%BE%84%E6%95%B4%E4%BD%93%E5%B7%B2%E8%B6%8A%E7%95%8C%22%5D%0A%20%20LESSON%20--%3E%20WHY%5B%22%E9%80%90%E8%BD%AE%E5%88%A4%E5%88%86%EF%BC%9A%E7%BB%99%E8%B7%AF%E5%BE%84%E4%B8%8A%E6%AF%8F%E4%B8%80%E6%AD%A5%E5%8D%95%E7%8B%AC%E5%BD%92%E8%B4%A3%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">「条件分布」翻译过来就是「看到目前为止的对话后，模型决定下一句怎么说」。每一步它都只判断眼前这一步合不合适，从没人教它「把整条对话连起来看」——这正是渐进升级能得手的根子。</span></p><p>判分窗口必须装下全会话：裁判看不全历史，边缘轮会被判合规，\\(h(t)\\) 整条曲线左移失真。<span class="marginnote">抽检要抽会话不抢单轮：最强的渐进脚本往往每一轮的输出截图都无懈可击，审核员单看任何一屏都会放行——失败只存在于轮与轮的连接处。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>脚本不是自然会话：真实用户的升级是噪声的、断续的，脚本是压力测试的上界，对外声明时不要把脚本 ASR 说成产品泄漏率。多语言脚本的成本高，至少在主力语言各放一套，别让英语数字代言全部市场。接口范围要显式声明：预填类脚本只在暴露补全的产品上跑，不出现在不该出现的攻击面（口径沿<a href="/llm/jailbreak">越狱评测</a>）。最后，多轮脚本同样会进回归集，去重与版本化沿用红队漏斗，不要另立一套账。</p><p><span class="marginnote">初学者容易把脚本 ASR 直接当成「产品上有多少用户会攻破模型」。实际上脚本是刻意设计的压力测试上界：真实用户很少步步紧逼二十轮。对外要声明这是脚本读数，别把最坏情况的数字说成日常泄漏率。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>评测对象从一轮换成路径：渐进升级、上下文压载、状态遗忘、接口面是四个机制来源。</li><li>逐轮判分、完整历史保留；拆成独立补全是协议失败，不是模型失败。</li><li>两个数字：累积 \\(\\mathrm{ASR}_T\\) 与首违轮分布 \\(h(t)\\)，平均值抹平的是产品最需要的信息。</li><li>脚本表面随机化防背题；判分窗口装下全会话。</li><li>抽检抽会话不抢单轮——最强脚本的每一屏都清白。</li><li>出处：Zheng et al., MT-Bench 的多轮协议口径；Ganguli et al., 2022 的攻击多样性；公开套件说明。</li></ul>',7))])}const F=s(d,[["render",h]]);export{T as __pageData,F as default};
